-- Venue Live Guest "Platform Charity Run". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara charityrun), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'charityrun', 'Platform Charity Run (lari amal)', 'charityrun', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 133, 'center 38%',
  $t${"name":"Charity Run","orn":"blossom","ui":{"ivory":"#FFF3F9","white":"#FFFFFF","soft":"#FFD9EB","soft2":"#F5A3CB","accent":"#E91E8C","deep":"#7A0F4D","ink":"#4A0E30","mute":"#9A5F80","line":"#F7CFE2","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFF9FC","ink":"#4A0E30","accent":"#E91E8C","gold":"#F5B700","leaf":"#FFD9EB","hbg":"rgba(255,243,249,.94)","hline":"#F5A3CB","motif":"blossom"},"hud":{"bg":"rgba(122,15,77,.88)","acc":"#FFD84D","on":"#4A0E30"},"scr":{"wine":"#7A0F4D","veil":"255,243,249"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'charityrun');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/charityrun/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/charityrun/balloons.webp","w":0.9,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/charityrun/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/charityrun/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/charityrun/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/charityrun/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/charityrun/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/charityrun/arch.webp"},"fountain":{"url":"/assets/live-decor/charityrun/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/charityrun/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/charityrun/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/charityrun/table.webp"},"banner":{"url":"/assets/live-decor/charityrun/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/charityrun/gifts.webp","w":1.8},"lamp":{"url":"/assets/live-decor/charityrun/lamp.webp","w":0.9,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/charityrun/rope.webp","w":0.9,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/charityrun/planter.webp","w":0.9,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/charityrun/bush.webp","w":0.9,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/charityrun/av_host.webp","name":"Pembawa Acara"},"av_l1":{"url":"/assets/live-decor/charityrun/av_l1.webp","name":"Kak Topi Kacamata"},"av_l2":{"url":"/assets/live-decor/charityrun/av_l2.webp","name":"Kak Rambut Perak"},"av_l3":{"url":"/assets/live-decor/charityrun/av_l3.webp","name":"Kak Kursi Roda"},"av_p1":{"url":"/assets/live-decor/charityrun/av_p1.webp","name":"Kak Visor Pink"},"av_p2":{"url":"/assets/live-decor/charityrun/av_p2.webp","name":"Kak Hijab Pink"},"av_p3":{"url":"/assets/live-decor/charityrun/av_p3.webp","name":"Kak Hijab Putih"}}$d$::jsonb, background_url = '/assets/live-decor/charityrun/painting.webp', active = true, updated_at = now() where key = 'charityrun';
